  "echo '{\"exit\": \"ask\"}'",
  "echo '{\"exit\": \"ship\"}'",
  "echo '{\"exit\": \"revise\"}'; exit 1",
  "echo '{\"exit\": \"dropped\"}'; exit 1",
  "echo '{\"exit\": \"shipped\"}'",
  "echo '{\"exit\": \"landed\"}'",
